import { Routes, Route, Navigate, useLocation, useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import Header from "./components/Header/Header";
import Footer from "./components/Footer/Footer";
import Login from "./components/Login/Login";
import Register from "./components/Register/Register";
import ProtectedRoute from "./components/Protected/ProtectedRoute";

// Admin Pages
import AdminDashboard from "./pages/Admin/AdminDashboard";
import UserManagement from "./pages/Admin/UserManagement";
import RoomManagement from "./pages/Admin/RoomManagement";
import BookingManagement from "./pages/Admin/BookingManagement";
import Reports from "./pages/Admin/Reports";
import Settings from "./pages/Admin/Settings";

// Receptionist Pages
import ReceptionistDashboard from "./pages/Receptionist/ReceptionistDashboard";
import BookingList from "./pages/Receptionist/BookingList";
import CreateBooking from "./pages/Receptionist/CreateBooking";
import ReceptionistRooms from "./pages/Receptionist/ReceptionistRooms";

// Customer Pages
import CustomerHome from "./pages/Customer/CustomerHome";
import MyBookings from "./pages/Customer/MyBookings";
import Profile from "./pages/Customer/Profile";
import RoomSearch from "./pages/Customer/RoomSearch";

// Maintenance Pages
import MaintenanceDashboard from "./pages/Maintenance/MaintenanceDashboard";
import MaintenanceRequests from "./pages/Maintenance/MaintenanceRequests";

function App() {
  const location = useLocation();
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  
  const isAuthPage =
    location.pathname === "/login" || location.pathname === "/register";

  // Load user from localStorage on mount
  useEffect(() => {
    const storedUser = localStorage.getItem('user');
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch (err) {
        console.error('Failed to parse user data:', err);
        localStorage.removeItem('user');
        localStorage.removeItem('token');
      }
    }
  }, []);

  // Handle login success
  const handleLoginSuccess = (userData) => {
    setUser(userData);
  };

  // Handle logout
  const handleLogout = () => {
    // Clear localStorage
    localStorage.removeItem('user');
    localStorage.removeItem('token');
    
    // Clear user state
    setUser(null);
    
    // Redirect to login page
    navigate('/login');
  };

  return (
    <>
      {!isAuthPage && (
        <Header 
          user={user} 
          role={user?.role || 'guest'}
          onLogout={handleLogout}
        />
      )}

      <Routes>
        {/* Public Routes */}
        <Route 
          path="/login" 
          element={<Login onLoginSuccess={handleLoginSuccess} />} 
        />
        <Route 
          path="/register" 
          element={<Register onRegisterSuccess={handleLoginSuccess} />} 
        />

        {/* Root redirect based on role */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <RoleBasedRedirect user={user} />
            </ProtectedRoute>
          }
        />

        {/* ===================== ADMIN ROUTES ===================== */}
        <Route
          path="/admin"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <Navigate to="/admin/dashboard" replace />
            </ProtectedRoute>
          }
        />

        <Route
          path="/admin/dashboard"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <AdminDashboard />
            </ProtectedRoute>
          }
        />

        <Route
          path="/admin/users"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <UserManagement />
            </ProtectedRoute>
          }
        />

        <Route
          path="/admin/rooms"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <RoomManagement />
            </ProtectedRoute>
          }
        />

        <Route
          path="/admin/bookings"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <BookingManagement />
            </ProtectedRoute>
          }
        />

        <Route
          path="/admin/reports"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <Reports />
            </ProtectedRoute>
          }
        />

        <Route
          path="/admin/settings"
          element={
            <ProtectedRoute allowedRoles={['admin']}>
              <Settings />
            </ProtectedRoute>
          }
        />

        {/* ===================== RECEPTIONIST ROUTES ===================== */}
        <Route
          path="/receptionist"
          element={
            <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
              <Navigate to="/receptionist/dashboard" replace />
            </ProtectedRoute>
          }
        />

        <Route
          path="/receptionist/dashboard"
          element={
            <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
              <ReceptionistDashboard />
            </ProtectedRoute>
          }
        />

        <Route
          path="/receptionist/booking-list"
          element={
            <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
              <BookingList />
            </ProtectedRoute>
          }
        />

        <Route
          path="/receptionist/create-booking"
          element={
            <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
              <CreateBooking />
            </ProtectedRoute>
          }
        />

        <Route
          path="/receptionist/rooms"
          element={
            <ProtectedRoute allowedRoles={['receptionist', 'admin']}>
              <ReceptionistRooms />
            </ProtectedRoute>
          }
        />

        {/* ===================== CUSTOMER ROUTES ===================== */}
        <Route
          path="/home"
          element={
            <ProtectedRoute allowedRoles={['customer']}>
              <CustomerHome />
            </ProtectedRoute>
          }
        />

        <Route
          path="/rooms"
          element={
            <ProtectedRoute allowedRoles={['customer']}>
              <RoomSearch />
            </ProtectedRoute>
          }
        />

        <Route
          path="/my-bookings"
          element={
            <ProtectedRoute allowedRoles={['customer']}>
              <MyBookings />
            </ProtectedRoute>
          }
        />

        <Route
          path="/profile"
          element={
            <ProtectedRoute allowedRoles={['customer', 'admin', 'receptionist', 'maintenance']}>
              <Profile />
            </ProtectedRoute>
          }
        />

        {/* ===================== MAINTENANCE ROUTES ===================== */}
        <Route
          path="/maintenance"
          element={
            <ProtectedRoute allowedRoles={['maintenance', 'admin']}>
              <Navigate to="/maintenance/dashboard" replace />
            </ProtectedRoute>
          }
        />

        <Route
          path="/maintenance/dashboard"
          element={
            <ProtectedRoute allowedRoles={['maintenance', 'admin']}>
              <MaintenanceDashboard />
            </ProtectedRoute>
          }
        />

        <Route
          path="/maintenance/requests"
          element={
            <ProtectedRoute allowedRoles={['maintenance', 'admin']}>
              <MaintenanceRequests />
            </ProtectedRoute>
          }
        />

        {/* 404 Route */}
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>

      {!isAuthPage && <Footer />}
    </>
  );
}

// Helper component for role-based redirect
const RoleBasedRedirect = ({ user }) => {
  if (!user) return <Navigate to="/login" replace />;

  const role = user.role?.toLowerCase();
  
  switch(role) {
    case 'admin':
      return <Navigate to="/admin/dashboard" replace />;
    case 'receptionist':
      return <Navigate to="/receptionist/dashboard" replace />;
    case 'maintenance':
      return <Navigate to="/maintenance/dashboard" replace />;
    case 'customer':
    default:
      return <Navigate to="/home" replace />;
  }
};

export default App;
